def process_state(transitions):
    # 进程状态机：事件序列 → 最终状态（就绪→运行→阻塞→就绪→终止）
    state = '就绪'
    for ev in transitions:
        if state == '就绪' and ev == '调度':
            state = '运行'
        elif state == '运行' and ev == 'IO等待':
            state = '阻塞'
        elif state == '阻塞' and ev == 'IO完成':
            state = '就绪'
        elif state == '运行' and ev == '完成':
            state = '终止'
    return state

