def parse_dom(html):
    # HTML → DOM 树（简化：标签 → 直接子标签列表）
    import re
    dom = {}
    stack = []
    for m in re.finditer(r'<(\w+)[^>]*>|</(\w+)>', html):
        if m.group(1):
            tag = m.group(1)
            dom.setdefault(tag, [])
            if stack:
                dom[stack[-1]].append(tag)
            stack.append(tag)
        elif m.group(2) and stack:
            stack.pop()
    return dom

