def ip_fragment(packet_size, mtu):
    # IP 分片：包大小 + MTU → 分片数（每片含 20B IP 头）
    import math
    if packet_size <= mtu:
        return 1
    payload = mtu - 20
    return math.ceil(packet_size / payload)

