def build_get_request(url, host, headers=None):
    # 构建 HTTP GET 请求：请求行 + Host 头 + 自定义头
    h = headers or {}
    lines = ['GET ' + url + ' HTTP/1.1', 'Host: ' + host]
    for k, v in h.items():
        lines.append(k + ': ' + v)
    return '\r\n'.join(lines) + '\r\n\r\n'

