def parse_url(url):
    # URL 解析：协议/主机/端口/路径
    import re
    m = re.match(r'(\w+)://([^/:]+)(?::(\d+))?(/.*)?', url)
    return {'scheme': m.group(1), 'host': m.group(2),
            'port': int(m.group(3)) if m.group(3) else None,
            'path': m.group(4) or '/'}

